def transform(grid):
    """Encode each 3x3 patch by its non-background, non-noise color."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            color = 0
            for rr in range(r, min(r + 3, h)):
                for cc in range(c, min(c + 3, w)):
                    value = grid[rr][cc]
                    if value not in (0, 5):
                        color = value
                        break
                if color:
                    break
            row.append(color)
        out.append(row)
    return out

